package lifequest.profile;

import lifequest.model.User;
import lifequest.ui.MascotPanel;
import lifequest.ui.Style;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;

public class ProfilePanel extends JPanel {
    public ProfilePanel(User user){setBackground(Style.BACKGROUND);setLayout(new BorderLayout(16,16));setBorder(new EmptyBorder(28,30,28,30));JLabel title=Style.title("Your Adventurer Profile");add(title,BorderLayout.NORTH);
        JPanel body=new JPanel(new GridLayout(1,2,16,16));body.setOpaque(false);JPanel left=Style.card();left.setLayout(new BoxLayout(left,BoxLayout.Y_AXIS));left.add(new MascotPanel());JLabel name=Style.title(user.getUsername());name.setAlignmentX(CENTER_ALIGNMENT);left.add(name);JLabel role=Style.label("✦ Level "+user.getLevel()+" Adventurer");role.setForeground(Style.MUTED);role.setAlignmentX(CENTER_ALIGNMENT);left.add(Box.createVerticalStrut(7));left.add(role);left.add(Box.createVerticalStrut(18));left.add(Style.title("Journey stats"));left.add(Box.createVerticalStrut(10));left.add(info("Total XP",String.valueOf(user.getXp())));left.add(info("Coins",String.valueOf(user.getCoins())));left.add(info("Email",user.getEmail()==null?"Not set":user.getEmail()));
        JPanel right=Style.card();right.setLayout(new BoxLayout(right,BoxLayout.Y_AXIS));right.add(Style.title("Character attributes"));right.add(Box.createVerticalStrut(15));stat(right,"Health",user.getHealth(),new Color(255,105,145));stat(right,"Focus",user.getFocus(),Style.ACCENT_BLUE);stat(right,"Discipline",user.getDiscipline(),Style.SUCCESS);stat(right,"Strength",user.getStrength(),new Color(255,190,92));right.add(Box.createVerticalStrut(18));right.add(Style.title("Achievements"));right.add(Box.createVerticalStrut(12));right.add(achievement("✦","First Steps","Start your adventure",user.getXp()>=0));right.add(Box.createVerticalStrut(8));right.add(achievement("★","Knowledge Seeker","Earn 100 XP",user.getXp()>=100));right.add(Box.createVerticalStrut(8));right.add(achievement("♛","Quest Master","Earn 500 XP",user.getXp()>=500));body.add(left);body.add(right);add(Style.scroll(body),BorderLayout.CENTER);}
    private JPanel info(String name,String value){JPanel r=new JPanel(new BorderLayout(10,0));r.setOpaque(false);r.setMaximumSize(new Dimension(Integer.MAX_VALUE,30));JLabel n=Style.label(name);n.setForeground(Style.MUTED);r.add(n,BorderLayout.WEST);r.add(Style.label(value),BorderLayout.EAST);return r;}
    private void stat(JPanel p,String name,int value,Color color){JPanel r=new JPanel(new BorderLayout(10,0));r.setOpaque(false);r.setMaximumSize(new Dimension(Integer.MAX_VALUE,26));JLabel n=Style.label(name);n.setPreferredSize(new Dimension(90,20));n.setForeground(Style.MUTED);JProgressBar b=new JProgressBar(0,100);b.setValue(Math.max(0,Math.min(100,value)));b.setForeground(color);b.setBackground(new Color(29,37,69));b.setBorderPainted(false);r.add(n,BorderLayout.WEST);r.add(b,BorderLayout.CENTER);r.add(Style.label(String.valueOf(value)),BorderLayout.EAST);p.add(r);p.add(Box.createVerticalStrut(12));}
    private JPanel achievement(String icon,String name,String desc,boolean unlocked){JPanel r=Style.card();r.setLayout(new BorderLayout(12,0));JLabel badge=Style.label(icon);badge.setFont(new Font("Segoe UI",Font.BOLD,23));badge.setForeground(unlocked?new Color(255,195,90):Style.MUTED);r.add(badge,BorderLayout.WEST);JPanel t=new JPanel();t.setOpaque(false);t.setLayout(new BoxLayout(t,BoxLayout.Y_AXIS));t.add(Style.label(name));JLabel d=Style.label(unlocked?desc:"Locked — "+desc);d.setForeground(Style.MUTED);d.setFont(new Font("Segoe UI",Font.PLAIN,11));t.add(d);r.add(t,BorderLayout.CENTER);return r;}
}